import { ViewElementBuilder } from "../../../assets";
import { State, StateConnector } from "../../../common";
import { ExternalTopbarDialog } from "../../../common/game-core";
import { OverlayScene } from "../../../common/scenes";
import { Locale, SoundKey } from "../../../logic";
import { GameServiceProvider } from "../../../services";

interface ISettingsState {
  isMusicOn: boolean;
  isSoundOn: boolean;
  locale: Locale;
}

interface IProps {
  scene: Phaser.Scene;
}

const DEFAULT_MUSIC_VOLUME = 0.09;

export class SettingsUi extends Phaser.GameObjects.Container {
  private readonly settingsState: State<ISettingsState>;
  private readonly settingsConnector: StateConnector<ISettingsState>;
  private dialog?: ExternalTopbarDialog;
  private readonly unSubs: Array<() => void> = [];
  private readonly musicVolume = DEFAULT_MUSIC_VOLUME;
  private isInputUnlocked = false;

  constructor(private readonly props: IProps) {
    super(props.scene);

    const gameService = GameServiceProvider.get();
    const initialSettings: ISettingsState = gameService.getPlayerData().settings;
    const onSettingsChange = (settings: ISettingsState) => gameService.setPlayerData({ settings });

    /** ставим настройки в наш стейт для отражения на UI **/
    this.settingsState = new State<ISettingsState>({ ...initialSettings });
    // коннектор передаем в диалог
    this.settingsConnector = new StateConnector<ISettingsState>(this.settingsState);

    /** подписка на изменения стейта - сохранения **/
    const saveState = (state: ISettingsState) => {
      onSettingsChange(state);
    };
    this.unSubs.push(this.settingsState.on(saveState));

    const { scene } = props;
    const builder = new ViewElementBuilder(scene);

    this.unSubs.push(() => OverlayScene.destroy());

    const button = builder.buttonSettings(() => this.showDialog());
    this.add(button);

    this.scene.add.existing(this);
    this.subscribeToState();
  }

  destroy() {
    super.destroy();
    this.unSubs.forEach((u) => u());
  }

  private subscribeToState() {
    const { scene } = this.props;
    // ждём первый ввод, чтобы легально стартовать музыку
    const onFirstPointer = () => {
      this.isInputUnlocked = true;
      this.applySound(this.settingsState.getState());
    };
    scene.input.once(Phaser.Input.Events.POINTER_DOWN, onFirstPointer);
    this.applySound(this.settingsState.getState());

    // подписка
    this.unSubs.push(this.settingsState.on((state) => this.applySound(state)));
  }

  private showDialog() {
    try {
      const overlayScene = OverlayScene.get(this.props.scene);
      if (this.dialog == null || !this.dialog.active || this.dialog.scene !== overlayScene) {
        const overlayBuilder = new ViewElementBuilder(overlayScene);
        this.dialog = overlayBuilder.dialogSettings({
          settings: this.settingsConnector,
        });
      }
      this.dialog.show();
    } catch (e) {
      console.warn(e);
    }
  }

  private applySound(state: ISettingsState) {
    this.props.scene.sound.mute = !state.isSoundOn;

    const soundOff = !state.isSoundOn;
    const musicOff = !state.isMusicOn;

    if (soundOff || musicOff) {
      this.stopMusic();
      return;
    }

    if (this.isInputUnlocked) {
      this.playOrResumeMusic();
    }
  }

  // пытается запустить или продолжить музыку при активных настройках
  private playOrResumeMusic() {
    try {
      const music =
        this.props.scene.sound.get(SoundKey.music) ?? this.props.scene.sound.add(SoundKey.music);

      if (music.isPlaying) return;
      if (music.isPaused) {
        music.resume();
        return;
      }
      music.play({ loop: true, volume: this.musicVolume });
    } catch (e) {
      console.warn(e);
    }
  }

  // стопает музыку при выключении звука/музыки
  private stopMusic() {
    try {
      const music = this.props.scene.sound.get(SoundKey.music);
      if (!music) return;
      if (music.isPlaying || music.isPaused) {
        music.stop();
      }
    } catch (e) {
      console.warn(e);
    }
  }
}
