import { KlondikeGameMove } from "../../../../../common";
import { SoundKey } from "../../../../../logic";

export function playSoundToKlondikeMove(scene: Phaser.Scene, move: KlondikeGameMove){
  if(move.type==='transfer' || move.type==='pickDeckCard'){
    scene.sound.play(SoundKey.cardFlip);
  } else if(move.type==='wrongDrop' || move.type==='wrongCard'){
    scene.sound.play(SoundKey.cardSfx03, { volume: 0.5 });
  } else if(move.type==='deckRecycle'){
    scene.sound.play(SoundKey.cardMultipleFlip);
  }
}
