import { Align, AlignObject, layoutRow } from "@kvisaz/phaser-sugar";

export interface ILayoutDefaultSpiderProps {
  scene: Phaser.Scene;
  stock: AlignObject;
  foundations: AlignObject[];
  tableaus: AlignObject[];
}

const cardTopPadding = 32;
const cardGap = 12;
const topToTableauGap = 28;

export function layoutDefaultSpider({ scene, stock, foundations, tableaus }: ILayoutDefaultSpiderProps): void {
  const topRow = layoutRow({
    children: [stock, ...foundations],
    nextOffsetX: cardGap,
  });

  const tableausRow = layoutRow({
    children: [...tableaus],
    nextOffsetX: cardGap,
  });

  const align = new Align();
  align.anchorSceneScreen(scene).topIn(topRow, cardTopPadding).centerX(topRow);
  align.anchor(topRow).bottomTo(tableausRow, topToTableauGap).centerX(tableausRow);

  [stock, ...foundations, ...tableaus].forEach((obj) =>
    scene.add.existing(obj as unknown as Phaser.GameObjects.GameObject),
  );
}

