import { CardSide, CardView } from "../../cards-abstract";
import { CardSuit, CardValue } from "../../cards-classic";
import { ISpiderCard } from "../types";

export type SpiderCardImage = Phaser.GameObjects.Image | Phaser.GameObjects.Container;

interface IProps {
  scene: Phaser.Scene;
  value: CardValue;
  suit: CardSuit;
  scale?: number;
  initStackId: string;
  initSide?: CardSide;
  faceImage: SpiderCardImage;
  backImage: SpiderCardImage;
}

export class SpiderCard extends CardView implements ISpiderCard {
  public readonly value: CardValue;
  public readonly suit: CardSuit;
  public readonly type = "SpiderCard";

  constructor({ suit, value, scale, ...props }: IProps) {
    super(props);
    this.suit = suit;
    this.value = value;
    if (scale) {
      this.setScale(scale);
    }
  }
}

