import { getUrlParam } from "../../common/utils/getUrlParam";
import { isAllowedHost } from "../../common/utils/isAllowedHost";

const ALLOWED_URL_STARTS = ["localhost", "kvisaz.github.io"];
const isMockDomain = () => isAllowedHost(ALLOWED_URL_STARTS);

export const isMockAdEnabled = () => {
  return isMockDomain() && getUrlParam("mockAd") !== null;
};

export const isMockShopEnabled = () => {
  return isMockDomain() && getUrlParam("mockShop") !== null;
};
