import { AlignObject, IBoundable } from "@kvisaz/phaser-sugar";
import { centeredCardLayoutStrategy, showValueCardFromTopLayoutStrategy } from "../cards-layout";
import { ICardPlace } from "../cards-abstract";
import { SpiderStack, SpiderStackMap } from "./cards";
import { SpiderStackType, SpiderStacksCreator } from "./types";
import { layoutDefaultSpider } from "./layoutDefaultSpider";

interface IProps {
  scene: Phaser.Scene;
  createCardPlace: () => ICardPlace;
}

const TABLEAUS_AMOUNT = 10;
const FOUNDATIONS_AMOUNT = 8;

const cardLayout = {
  stock: centeredCardLayoutStrategy,
  foundation: centeredCardLayoutStrategy,
  tableau: (cards: AlignObject[], inputZone: IBoundable) =>
    showValueCardFromTopLayoutStrategy(cards, inputZone, { offsetY: 32 }),
} as const;

export function createDefaultSpiderStacksCreator({ scene, createCardPlace }: IProps): SpiderStacksCreator {
  return () => {
    const stock = new SpiderStack({
      id: SpiderStackType.STOCK,
      type: SpiderStackType.STOCK,
      cardPlace: createCardPlace(),
      layoutStrategy: cardLayout.stock,
    });

    const foundations = Array.from(new Array(FOUNDATIONS_AMOUNT)).map(
      (_, index) =>
        new SpiderStack({
          id: `${SpiderStackType.FOUNDATION}-${index}`,
          type: SpiderStackType.FOUNDATION,
          cardPlace: createCardPlace(),
          layoutStrategy: cardLayout.foundation,
        }),
    );

    const tableaus = Array.from(new Array(TABLEAUS_AMOUNT)).map(
      (_, index) =>
        new SpiderStack({
          id: `${SpiderStackType.TABLEAU}-${index}`,
          type: SpiderStackType.TABLEAU,
          cardPlace: createCardPlace(),
          layoutStrategy: cardLayout.tableau,
        }),
    );

    layoutDefaultSpider({
      scene,
      stock: stock.cardPlace,
      foundations: foundations.map((s) => s.cardPlace),
      tableaus: tableaus.map((s) => s.cardPlace),
    });

    return new SpiderStackMap([stock, ...foundations, ...tableaus]);
  };
}

