import { ViewElementBuilder } from "../../../../assets";
import { EmitterOnly } from "../../../../common";
import { OverlayScene } from "../../../../common/scenes";
import { CenteredContainerButton, ExternalTopbarDialog } from "../../../../common/game-core";
import { ILogicShopItem, PurchaseId } from "../../../../logic";
import { IGameViewEvents } from "../../logic";
import { IShopOverlayState, ShopOverlayLogic } from "./ShopOverlayLogic";

interface IProps {
  scene: Phaser.Scene;
  gameSceneViewEvents: EmitterOnly<IGameViewEvents>;
}

/**
 *  Кнопка магазина
 *  и диалог магазина который вызывается по нажатию на кнопку
 *  магазин читает данные из сервисов
 *  - PlayerDataService
 *  - ShopDataService
 *
 *  отправляет данные в
 *  - ShopDataService - о желании покупки
 *  - PlayerDataService - о зачислении покупки
 **/
export class ShopOverlay extends Phaser.GameObjects.Container {
  /** нужно только для открытия диалога в окне поверх **/
  private readonly unSubs: Array<() => void> = [];
  private dialog?: ExternalTopbarDialog;
  private button: CenteredContainerButton;
  private logic: ShopOverlayLogic;

  constructor(private readonly props: IProps) {
    super(props.scene);

    /**
     * логика связи с источником данных
     * пока я решил что у нас данные не меняются в течение жизни
     * но в архитектуру заложим гибкую реакцию
     * **/
    /**
     * Важно: логика читает данные только при создании.
     * Если ShopService.preload еще не завершен, диалог может остаться пустым.
     * При необходимости добавь обновление по событию или при открытии диалога.
     */
    this.logic = new ShopOverlayLogic({ scene: props.scene });
    this.unSubs.push(() => this.logic.destroy());

    const builder = new ViewElementBuilder(props.scene);
    const button = builder.buttonShop(() => this.showDialog());
    this.add(button);
    this.button = button;
    this.scene.add.existing(this);

    // подписываемся на кнопку
    this.logic.observable.on(this.applyButtonState.bind(this), "isButtonEnabled");
    // применяем актуальные данные
    this.applyButtonState();
  }

  destroy() {
    super.destroy();
    this.unSubs.forEach((u) => u());
    this.resumeSound();
    OverlayScene.destroy();
  }

  private applyButtonState(state: IShopOverlayState = this.logic.observable.getState()) {
    this.button.setVisible(state.isButtonEnabled);
  }

  private showDialog() {
    const overlayScene = OverlayScene.get(this.props.scene);
    this.pauseSound();

    /** есть ли что показывать, если нет - просто не включаем **/
    const { shopItems } = this.logic.observable.getState();
    if (shopItems == null) {
      this.resumeSound();
      this.dialog?.destroy();
      this.dialog = undefined;
      this.button.setVisible(false);
      return;
    }

    /** создаем и показываем диалог в любом случае **/
    this.dialog?.destroy();
    const builder = new ViewElementBuilder(overlayScene);
    this.dialog = builder.dialogShop({
      shopItems: Object.values(shopItems),
      onItemBuyClick: this.onItemBuyClick.bind(this),
      onClose: this.onClose.bind(this),
    });

    this.dialog?.show();
  }

  private async onItemBuyClick(item: ILogicShopItem) {
    try {
      const result = await this.logic.onItemBuyClick(item);
      if ("error" in result) {
        console.warn("shop purchase failed", result.error);
        return;
      }
      this.props.gameSceneViewEvents.emit("onShopPurchaseApplied", {
        purchaseId: item.id as PurchaseId,
      });
    } catch (e) {
      console.warn(e);
    }
  }

  private onClose() {
    this.resumeSound();
  }

  private pauseSound() {
    this.props.scene.sound.pauseAll();
  }

  private resumeSound() {
    this.props.scene.sound.resumeAll();
  }
}
