import { getDefaultPurchaseLedgerState, PurchaseLedgerState } from "./types";

export type PurchaseLedgerStore = {
  get(): PurchaseLedgerState;
  set(next: PurchaseLedgerState): void;
};

export class InMemoryPurchaseLedgerStore implements PurchaseLedgerStore {
  private state: PurchaseLedgerState;

  constructor(initial?: PurchaseLedgerState) {
    this.state = initial ?? getDefaultPurchaseLedgerState();
  }

  get(): PurchaseLedgerState {
    return this.state;
  }

  set(next: PurchaseLedgerState): void {
    this.state = next;
  }
}

