import { SDK } from "ysdk";
import {
  ConsumableType,
  ILogicShopItem,
  InAppPurchaseId,
  IShopConfig,
  IShopItemConfig,
  ShopPack,
} from "../../logic";
import { getErrorMessage } from "../../common/string/getErrorMessage";
import { InAppApiService, PendingInAppPurchase, ShopPurchaseResult } from "./types";
import { isMockShopEnabled } from "../GameService/mockGetters";
import { MockInAppService } from "./MockInAppService";
import { YandexInAppService } from "./YandexInAppService";
import { api2logicItem } from "../../logic/shop/mappers";
import { GameServicePlayerData } from "../GameService/types";
import { IAdService } from "../../common/ads";
import { PurchaseLedgerEntry, PurchaseLedgerStore } from "../../common/services/payments/purchaseLedger";

type RewardAdResult = { wasShown: boolean; isReward: boolean; error?: string };

type PlayerDataService = {
  setPlayerData(partial: Partial<GameServicePlayerData>): void;
  getPlayerData(): GameServicePlayerData;
  /**
   * Немедленно сохраняет playerData без debounce.
   * Важно для покупок: consume нельзя делать, пока состояние не сохранено.
   */
  savePlayerDataNow(): Promise<void>;
};

interface IProps {
  shopConfig: IShopConfig;
  isMockShop?: boolean;
  sdk?: SDK;
  showRewardedAd: () => Promise<RewardAdResult>;
  playerDataService: PlayerDataService;
  purchaseLedgerStore: PurchaseLedgerStore;
  adService?: IAdService;
  isRewardAdEnable: () => boolean;
}

/**
 * Магазинчик конкретной игры
 * - держит реестр возможных покупок за валюту и рекламу
 * - обрабатывает клики
 * - зачисляет на баланс
 * **/
export class ShopService {
  private logicShopItems: Record<string, ILogicShopItem>;
  private inAppApiService?: InAppApiService;

  constructor(private props: IProps) {
    this.logicShopItems = {};
  }

  async preload() {
    try {
      await this.initApi();
      /** Если подключили API магазина
       * - проверяем какие покупки доступны, проставляем цены **/
      if (this.inAppApiService) {
        this.initInAppShopItems({
          api: this.inAppApiService,
          shopConfig: this.props.shopConfig,
        });
      }

      /** Если доступна реклама - обновляем покупки за рекламу
       * - проверяем какие покупки доступны, проставляем цены **/
      this.initRewardableShopItems();
    } catch (e) {
      console.warn(e);
    }
  }

  /**
   * Восстанавливает покупки после перезагрузки/краша:
   * - читает pending покупки у платформы
   * - начисляет награду (один раз, идемпотентно по purchaseToken)
   * - делает consume только после успешного сохранения
   *
   * Должно вызываться после загрузки playerData (иначе сохранение может быть перетёрто readPlayerData()).
   */
  async reconcilePendingPurchases(): Promise<void> {
    const api = this.inAppApiService;
    if (api == null) return;
    try {
      const pending = await api.getPendingPurchases();
      for (const purchase of pending) {
        try {
          await this.grantAndConsume(purchase);
        } catch (e) {
          console.warn("grantAndConsume failed", purchase.productID, e);
        }
      }
    } catch (e) {
      console.warn("reconcilePendingPurchases failed", e);
    }
  }

  getShopItems(): Record<string, ILogicShopItem> {
    return this.logicShopItems;
  }

  /** Магазин доступен, если
   * - есть покупки
   * - есть покупки за рекламу и разрешена реклама
   * **/
  isShopEnabled(isRewardAdEnabled: boolean): boolean {
    const inAppItems: ILogicShopItem[] = [];
    const rewardItems: ILogicShopItem[] = [];
    Object.values(this.logicShopItems).forEach((item) => {
      const hasPrice = item.price != null && item.currency != null;
      if (hasPrice) inAppItems.push(item);
      if (item.rewardAdPrice) rewardItems.push(item);
    });
    const hasRewards = rewardItems.length > 0;
    const hasInApps = inAppItems.length > 0;

    return (isRewardAdEnabled && hasRewards) || hasInApps;
  }

  async shopPurchase(id: string): Promise<ShopPurchaseResult> {
    if (this.isInAppId(id)) {
      return this.purchaseInApp(id);
    } else {
      return this.purchaseReward(id);
    }
  }

  private async purchaseInApp(id: InAppPurchaseId): Promise<ShopPurchaseResult> {
    if (this.inAppApiService == null) {
      return { error: "shop not available" };
    }
    try {
      const purchase = await this.inAppApiService.purchase(id);
      await this.grantAndConsume(purchase);
      return { purchaseId: id };
    } catch (e) {
      return { error: getErrorMessage(e), purchaseId: id };
    }
  }

  private async purchaseReward(id: string): Promise<ShopPurchaseResult> {
    const purchase = this.logicShopItems[id];
    if (purchase == null) {
      return { error: `no reward purchase with id ${id}` };
    }
    const adResult = await this.props.showRewardedAd();
    if (!adResult.isReward) {
      return { error: adResult.error ?? "reward ad not completed", purchaseId: id };
    }
    try {
      this.applyRewardPurchaseToPlayer(id);
    } catch (e) {
      return { error: getErrorMessage(e), purchaseId: id };
    }
    return { purchaseId: id };
  }

  private async initApi(): Promise<void> {
    if (this.inAppApiService != null) return;
    if (isMockShopEnabled() || this.props.isMockShop) {
      const availablePurchaseIds = this.props.shopConfig.items
        .filter((item) => item.isPurchase)
        .map((item) => item.id);

      this.inAppApiService = new MockInAppService({
        availablePurchaseIds,
      });
    } else {
      const { sdk } = this.props;
      if (sdk == null) return;
      this.inAppApiService = new YandexInAppService({
        sdk,
      });
    }

    try {
      await this.inAppApiService.preload();
    } catch (e) {
      console.warn("inAppApiService preload failed", e);
    }
  }

  /**
   * Главная транзакция покупки:
   * - начислить награду (один раз по purchaseToken)
   * - сохранить playerData
   * - сделать consume
   *
   * Если награда не может быть начислена (unknown id / non-consumable) — consume не делаем,
   * иначе покупка будет “потеряна” (списана без выдачи).
   */
  private async grantAndConsume(purchase: PendingInAppPurchase): Promise<void> {
    const token = purchase.purchaseToken;
    const now = Date.now();

    const playerDataBefore = this.props.playerDataService.getPlayerData();
    const ledger = this.props.purchaseLedgerStore.get().grantedButNotConsumed;

    /** Уже начисляли, но не успели consume (например, упали на consume) — просто ретраим consume. */
    if (ledger[token] != null) {
      await this.inAppApiService?.consumePurchase(token);
      await this.removeTokenFromLedger(token);
      return;
    }

    const pack = this.getShopPackForPurchaseId(purchase.productID);
    if (pack == null) {
      console.warn("unknown purchase id, skip consume", purchase.productID);
      return;
    }

    if (pack.type !== "consumables") {
      /**
       * Сейчас в GamePlayerData нет места, где хранить entitlement вроде `ad_free`.
       * Поэтому мы НЕ делаем consume, иначе покупка исчезнет навсегда без активации.
       */
      console.warn("non-consumable purchase is not supported yet, skip consume", purchase.productID);
      return;
    }

    /** 1) Начисляем награду + фиксируем token в ledger. */
    const newConsumables = this.buildNewConsumables(playerDataBefore, pack.data);
    const newLedger: Record<string, PurchaseLedgerEntry> = {
      ...ledger,
      [token]: { productID: purchase.productID, ts: now },
    };
    this.props.purchaseLedgerStore.set({ grantedButNotConsumed: newLedger });
    this.props.playerDataService.setPlayerData({ consumables: newConsumables });

    /** 2) Сохраняем (без debounce). Только после этого можно делать consume. */
    await this.props.playerDataService.savePlayerDataNow();

    /** 3) consume. Если упадёт — токен останется в ledger и будет обработан при следующем старте. */
    await this.inAppApiService?.consumePurchase(token);

    /** 4) Убираем токен из ledger (best-effort). */
    await this.removeTokenFromLedger(token);
  }

  private buildNewConsumables(
    playerData: GameServicePlayerData,
    consumablesIncrement: Partial<Record<ConsumableType, number>>,
  ): Record<ConsumableType, number> {
    const newConsumables: Record<ConsumableType, number> = {
      ...playerData.consumables,
    };
    Object.entries(consumablesIncrement).forEach(([key, amount]) => {
      const type = key as ConsumableType;
      const inc = amount ?? 0;
      newConsumables[type] = newConsumables[type] + inc;
    });
    return newConsumables;
  }

  private applyRewardPurchaseToPlayer(shopItemId: string): void {
    const item = this.logicShopItems[shopItemId];
    if (!item) {
      console.warn("no shop item for id", shopItemId);
      return;
    }
    if (item.shopPack.type !== "consumables") {
      return;
    }
    const playerData = this.props.playerDataService.getPlayerData();
    const newConsumables = this.buildNewConsumables(playerData, item.shopPack.data);
    this.props.playerDataService.setPlayerData({ consumables: newConsumables });
  }

  private getShopPackForPurchaseId(purchaseId: string): ShopPack | undefined {
    return this.props.shopConfig.items.find((item) => item.id === purchaseId && item.isPurchase)?.shopPack;
  }

  private async removeTokenFromLedger(token: string): Promise<void> {
    try {
      const current = this.props.purchaseLedgerStore.get().grantedButNotConsumed;
      if (current[token] == null) return;
      const { [token]: _removed, ...rest } = current;
      this.props.purchaseLedgerStore.set({ grantedButNotConsumed: rest });
      await this.props.playerDataService.savePlayerDataNow();
    } catch (e) {
      console.warn("removeTokenFromLedger failed", e);
    }
  }

  private initInAppShopItems({
    api,
    shopConfig,
  }: {
    api: InAppApiService;
    shopConfig: IShopConfig;
  }) {
    const apiShopItems = api.getShopData() ?? [];
    apiShopItems.forEach((apiShopItem) => {
      const logicItem = api2logicItem(apiShopItem, shopConfig.items);
      if (logicItem) {
        this.logicShopItems[logicItem.id] = logicItem;
      }
    });
  }

  private initRewardableShopItems() {
    const { adService } = this.props;
    /** нет рекламного сервиса - не показываем **/
    if (adService == null) return;

    /** добавляем рекламные итемы из конфига **/
    const rewardConfigs = this.getRewardShopItemConfigs();
    console.log('rewardConfigs', rewardConfigs);
    rewardConfigs.forEach((itemConfig) => {
      this.logicShopItems[itemConfig.id] = {
        id: itemConfig.id,
        shopPack: itemConfig.shopPack,
        rewardAdPrice: true,
      };
    });
  }

  private getRewardShopItemConfigs(): IShopItemConfig[] {
    return this.props.shopConfig.items.filter((item) => item.isReward);
  }

  private getInAppShopItemConfig(): IShopItemConfig[] {
    return this.props.shopConfig.items.filter((item) => item.isPurchase);
  }

  private isInAppId(id: string): id is InAppPurchaseId {
    return this.props.shopConfig.items.some((item) => item.id === id && item.isPurchase);
  }
}
