import { Purchase, SDK } from "ysdk";
import { getSafeNumber } from "../../common/mapAndObjects/getSafeNumber";
import { getErrorMessage } from "../../common/string/getErrorMessage";
import { InAppApiService, PendingInAppPurchase, ShopServiceState } from "./types";
import { IApiShopItem } from "../../logic";

interface IShopServiceProps {
  sdk: SDK;
}

/**
 *  Этот сервис привязан к Яндекс Сервису
 *  - поэтому надо менять нейминг
 **/
export class YandexInAppService implements InAppApiService {
  private state: ShopServiceState = {};

  constructor(private readonly props: IShopServiceProps) {}

  /**
   * подключаем API
   * - читаем каталог покупок
   * **/
  async preload(): Promise<void> {
    try {
      const payments = await this.props.sdk.getPayments();
      if (payments == null) return;
      this.state.payments = payments;
      this.state.products = await payments.getCatalog();
    } catch (e) {
      console.warn(e);
    }
  }

  /** Здесь логика Яндекса смешивается с логикой конкретной игры
   *  todo надо чтобы он просто возвращал массив доступных ID или еще лучше Set
   * **/
  getShopData(): Set<IApiShopItem> | undefined {
    const products = this.state.products;
    if (products == null) return;
    const set = new Set<IApiShopItem>();
    for (const product of products) {
      set.add({
        id: product.id,
        price: getSafeNumber(product.priceValue),
        currency: product.priceCurrencyCode,
      });
    }
    return set;
  }

  /**
   *  покупка с зачислением на баланс
   *
   *  Важно: начисление и consume — ответственность ShopService.
   * **/
  async purchase(purchaseId: string): Promise<PendingInAppPurchase> {
    const payments = this.state.payments;
    if (payments == null) {
      throw new Error("payments not available");
    }

    let purchase: Purchase;
    try {
      purchase = await payments.purchase({ id: purchaseId });
    } catch (e) {
      throw new Error(getErrorMessage(e));
    }

    return {
      productID: purchase.productID,
      purchaseToken: purchase.purchaseToken,
      developerPayload: purchase.developerPayload,
    };
  }

  async getPendingPurchases(): Promise<PendingInAppPurchase[]> {
    const payments = this.state.payments;
    if (payments == null) return [];
    try {
      const purchases = await payments.getPurchases();
      return purchases.map((purchase) => ({
        productID: purchase.productID,
        purchaseToken: purchase.purchaseToken,
        developerPayload: purchase.developerPayload,
      }));
    } catch (e) {
      throw new Error(getErrorMessage(e));
    }
  }

  async consumePurchase(purchaseToken: string): Promise<void> {
    const payments = this.state.payments;
    if (payments == null) throw new Error("payments not available");
    await payments.consumePurchase(purchaseToken);
  }
}
