import { CachedDataService } from "./types";

interface IProps {
  appId: string;
}

export class LocalDataService implements CachedDataService {
  private cache: Record<string, unknown | undefined>;

  get storageKey() {
    return `${this.props.appId}-local`;
  }

  constructor(private props: IProps) {
    this.cache = {};
  }

  async preload(): Promise<void> {
    try {
      this.loadCache();
    } catch (e) {
      console.warn(e);
    }
  }

  getData<T>(key: string): T | undefined {
    return this.cache[key] as T | undefined;
  }

  setData<T>(key: string, value: T): Promise<void> {
    return this.setDataMany({ [key]: value });
  }

  setDataMany(values: Record<string, unknown>): Promise<void> {
    Object.entries(values).forEach(([key, value]) => {
      this.cache[key] = value;
    });
    /**
     * localStorage для нас best-effort:
     * - это не "источник правды" для покупок/баланса
     * - ошибки не должны ломать приложение
     */
    this.saveCache();
    return Promise.resolve();
  }

  private saveCache() {
    try {
      localStorage.setItem(this.storageKey, JSON.stringify(this.cache));
    } catch (e) {
      console.warn("localStorage setItem failed", e);
    }
  }

  private loadCache() {
    let saved: string | null = null;
    try {
      saved = localStorage.getItem(this.storageKey);
    } catch (e) {
      console.warn("localStorage getItem failed", e);
      return;
    }
    if (!saved) return;

    const parsed: unknown = JSON.parse(saved);
    if (parsed && typeof parsed === "object" && !Array.isArray(parsed)) {
      this.cache = parsed as Record<string, unknown>;
    }
  }
}
