import { ViewElementBuilder } from "../../../../assets";
import {
  createDefaultSpiderStacksCreator,
  defaultSpiderConfig,
  IClassicCardDto,
  ISpiderConfig,
  SpiderCard,
  SpiderStackType,
  SpiderView,
  TypedEventsEmitter,
} from "../../../../common";
import { SoundKey } from "../../../../logic";
import { ISpiderGameLogicCommandEvents, ISpiderGameViewEvents } from "../../logic";

interface IProps {
  scene: Phaser.Scene;
  spiderSceneLogicCommands: TypedEventsEmitter<ISpiderGameLogicCommandEvents>;
  spiderSceneViewEvents: TypedEventsEmitter<ISpiderGameViewEvents>;
}

export class SpiderWrap {
  private readonly builder: ViewElementBuilder;
  private spiderView: SpiderView | undefined;
  private readonly unSubs: Array<() => void> = [];

  constructor(private readonly props: IProps) {
    const { scene } = this.props;
    this.builder = new ViewElementBuilder(scene);
    this.subscribeToLogicCommands();
  }

  destroy() {
    this.spiderView?.destroy();
    this.unSubs.forEach((unSub) => unSub());
  }

  private subscribeToLogicCommands() {
    const { spiderSceneLogicCommands } = this.props;
    const getEvents = () => this.spiderView?.userEvents;

    spiderSceneLogicCommands.on("startSpider", (data) => this.start(data.cards, data.config));
    spiderSceneLogicCommands.on("undoSpider", () => getEvents()?.emit("onUndoClick"));
    spiderSceneLogicCommands.on("hintSpider", () => getEvents()?.emit("onHintClick"));
    spiderSceneLogicCommands.on("dealSpider", () => getEvents()?.emit("onDealClick"));
    spiderSceneLogicCommands.on("collectSpider", () => getEvents()?.emit("onCollectClick"));
  }

  private start(playCards: IClassicCardDto[], config: ISpiderConfig) {
    this.spiderView?.destroy();

    const { scene } = this.props;
    const builder = this.builder;

    const cardViews = playCards.map(
      ({ value, suit }) =>
        new SpiderCard({
          scene,
          suit,
          value,
          initStackId: SpiderStackType.STOCK,
          initSide: "back",
          faceImage: builder.cardFace(suit, value),
          backImage: builder.cardBack(),
        }),
    );

    const stackMap = createDefaultSpiderStacksCreator({
      scene,
      createCardPlace: () => builder.cardPlace(),
    })();

    const spiderView = new SpiderView({
      cardViews,
      stackMap,
      config: config ?? defaultSpiderConfig,
    });
    this.subscribeToSpiderEvents(spiderView);
    this.spiderView = spiderView;
  }

  private subscribeToSpiderEvents(spiderView: SpiderView) {
    const { scene, spiderSceneViewEvents } = this.props;

    spiderView.liveState.on((state) => {
      scene.input.enabled = state.step === "idle";
      spiderSceneViewEvents.emit("spiderStateUpdate", state);
    });
    spiderSceneViewEvents.emit("spiderStateUpdate", spiderView.liveState.getState());

    spiderView.gameEvents.on("win", () => spiderSceneViewEvents.emit("spiderWin"));

    spiderView.gameEvents.on("wrongAutoMove", () => {
      scene.sound.play(SoundKey.cardSfx03, { volume: 0.5 });
    });
  }
}
