export type PurchaseToken = string;

export type PurchaseLedgerEntry = {
  /** id товара (productID) */
  productID: string;
  /** timestamp (ms) когда мы начислили награду игроку */
  ts: number;
};

/**
 * Ledger покупок для идемпотентности:
 * если игра выдала награду, но не успела сделать consume (или упала),
 * на следующем старте мы НЕ выдаём награду повторно, а только ретраим consume.
 */
export type PurchaseLedgerState = {
  grantedButNotConsumed: Record<PurchaseToken, PurchaseLedgerEntry>;
};

export const getDefaultPurchaseLedgerState = (): PurchaseLedgerState => ({
  grantedButNotConsumed: {},
});

export const coercePurchaseLedgerState = (raw: unknown): PurchaseLedgerState => {
  if (raw == null || typeof raw !== "object" || Array.isArray(raw)) {
    return getDefaultPurchaseLedgerState();
  }

  const grantedRaw = (raw as { grantedButNotConsumed?: unknown }).grantedButNotConsumed;
  if (grantedRaw == null || typeof grantedRaw !== "object" || Array.isArray(grantedRaw)) {
    return getDefaultPurchaseLedgerState();
  }

  const grantedButNotConsumed: Record<PurchaseToken, PurchaseLedgerEntry> = {};
  Object.entries(grantedRaw as Record<string, unknown>).forEach(([token, entry]) => {
    if (entry == null || typeof entry !== "object" || Array.isArray(entry)) return;
    const productID = (entry as { productID?: unknown }).productID;
    const ts = (entry as { ts?: unknown }).ts;
    if (typeof productID !== "string") return;
    if (typeof ts !== "number") return;
    grantedButNotConsumed[token] = { productID, ts };
  });

  return { grantedButNotConsumed };
};

