import { ConsumableShopPack, ConsumableType } from "./types";

export function mapConsumableShopPackToArray(shopPack: ConsumableShopPack) {
  return Object.entries(shopPack.data)
    .map((entry) => ({
      type: entry[0] as ConsumableType,
      amount: entry[1],
    }))
    .filter((c) => c.amount > 0)
    .sort((a, b) => a.amount - b.amount);
}
