import { PreloadTask } from "@kvisaz/phaser-sugar";
import { addHtmlLoaderToPhaser, getUrlParam } from "../../common";
import { Scenes } from "../../common/game-core";
import { ViewElementBuilder } from "../../assets";
import { GameServiceProvider } from "../../services";

export class BootScene extends Phaser.Scene {
  constructor() {
    super(Scenes.Boot);
  }

  preload() {
    addHtmlLoaderToPhaser({
      scene: this,
      loaderVarHosId: "loader",
      cssVarProgressName: "--progress",
    });

    new ViewElementBuilder(this).preload();
    PreloadTask.load(this, GameServiceProvider.get().preload());
  }

  create() {
    GameServiceProvider.get().signalGameReady();
    this.scene.launch(Scenes.Game);
  }
}
