import { HtmlBackground } from "../../../../common/html";

/** настраивает фон html целиком, при дестрое восстанавливает предыдущий **/
export class Background extends Phaser.GameObjects.Container {
  private htmlBg: HtmlBackground;

  constructor(scene: Phaser.Scene, imageUrl: string, fallbacksUrl?: string[]) {
    super(scene);
    this.htmlBg = new HtmlBackground({
      url: imageUrl,
      fallbackUrl: fallbacksUrl?.[0]
    });
  }

  destroy(fromScene?: boolean) {
    this.htmlBg.destroy();
    super.destroy(fromScene);
  }
}
